<template>
  <view class="trend-insight">
    <view class="list-meta"><text class="list-title">趋势股列表</text><view class="list-meta-right"><view class="list-action" @tap="openPodcast"><SvgIcon name="broadcast-line" size="30rpx" color="#0b5fff" /></view><view class="list-action" @tap="refresh"><SvgIcon name="refresh-line" size="32rpx" color="#0b5fff" /></view><text v-if="latestDate" class="updated-date">{{ latestDate }}</text><text class="stock-count">{{ filteredStocks.length }} 只</text></view></view>
    <LoadingState v-if="loading" text="正在加载趋势评分" />
    <view v-else-if="errorMessage" class="state-panel"><SvgIcon name="error-warning-line" size="64rpx" color="#f59e0b" /><text class="state-title">趋势评分暂时无法加载</text><text class="state-desc">{{ errorMessage }}</text><button class="retry-button" @tap="loadTopStocks">重新加载</button></view>
    <EmptyState v-else-if="!filteredStocks.length" icon="search-eye-line" text="没有找到匹配的趋势股" />
    <view v-else class="stock-list"><view v-for="stock in filteredStocks.slice(0, 5)" :key="stock.symbol" class="stock-row" @tap="openDetail(stock)"><view class="stock-main"><text class="stock-name">{{ stock.name || stock.symbol }}</text><view class="stock-meta"><text class="stock-symbol">{{ stock.symbol }}</text><text v-if="stock.industry" class="industry-tag">{{ stock.industry }}</text></view></view><view class="score-block"><text class="total-score">{{ stock.score }}</text></view><text :class="['grade', `grade-${stock.label.toLowerCase()}`]">{{ stock.label }}</text><SvgIcon name="arrow-right-s-line" size="30rpx" color="#c6cad2" /></view><view v-if="filteredStocks.length > 5" class="view-all" @tap="goAll">查看全部 <text>›</text></view><view class="list-footnote">评分基于公开数据与模型测算，仅供参考，不构成投资建议。</view></view>
  </view>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { trendScoreApi, type TrendScoreListItem } from '@/shared/api/modules/trend-score'
import SvgIcon from '@/shared/components/SvgIcon.vue'
import LoadingState from '@/shared/components/LoadingState.vue'
import EmptyState from '@/shared/components/EmptyState.vue'
import { useReportPodcast } from '@/shared/utils/useReportPodcast'
const { loadPodcast, openPodcast: showPodcast } = useReportPodcast('trend_score')
const stocks = ref<TrendScoreListItem[]>([]); const loading = ref(false); const errorMessage = ref('')
const filteredStocks = computed(() => stocks.value)
const latestDate = computed(() => String(stocks.value[0]?.scoreDate || '').slice(0, 10))
async function loadTopStocks() { loading.value = true; errorMessage.value = ''; try { const result = await trendScoreApi.getTop(30); stocks.value = Array.isArray(result) ? result : [] } catch (error: unknown) { const item = error as { errMsg?: string; message?: string }; errorMessage.value = item.errMsg || item.message || '请稍后重试' } finally { loading.value = false } }
function openDetail(stock: TrendScoreListItem) { const name = encodeURIComponent(stock.name || stock.symbol); uni.navigateTo({ url: `/modules/analytics/pages/trend-score-detail?symbol=${stock.symbol}&name=${name}` }) }
function goAll() { uni.navigateTo({ url: '/modules/analytics/pages/trend-score' }) }
function openPodcast() { showPodcast('趋势股评分播报') } function refresh() { void loadTopStocks() }
onMounted(() => { void loadTopStocks(); void loadPodcast() })
</script>
