de-s{background:$stock-up-color}.grade-a{background:$brand-color}.grade-b,.grade-c,.grade-d{background:$text-color-secondary}.view-all{padding:$s-2 $spacing-base $spacing-sm;color:$text-color-tertiary;font-size:$font-size-base;text-align:center}.view-all text{margin-left:8rpx;font-size:$font-size-xl;color:$ink-faint}.list-footnote{padding:$spacing-base $spacing-sm;color:$text-color-tertiary;font-size:$font-size-xs;line-height:1.6;text-align:center}.state-panel{padding:80rpx $spacing-lg;display:flex;flex-direction:column;align-items:center;border-radius:$radius-lg;background:$bg-color-grey}.state-title{margin-top:$spacing-sm;color:$text-color-title;font-size:$font-size-lg;font-weight:600}.state-desc{margin-top:$spacing-xs;color:$text-color-secondary;font-size:$font-size-sm;text-align:center}.retry-button{margin-top:$spacing-base;padding:0 $spacing-lg;border:0;border-radius:$radius-pill;background:$brand-color;color:$bg-color-grey;font-size:$font-size-sm;line-height:64rpx}.retry-button::after{border:0}
</style>
